import stylesText from './ai-chat.css?inline';
import { cssStyleSheet } from '../../../utils/css.js';
import { createComponentLogger } from '../../../utils/component-logger.js';
import { AiService } from '../../../services/ai.service.js';

const styles = cssStyleSheet(stylesText);
const log = createComponentLogger('ai/ai-chat');

const template = document.createElement('template');
template.innerHTML = `
    <p class="message" id="loading">Loading...</p>
    <p class="message" id="off" hidden>Local AI is off. <a href="/ai">Turn it on</a> to chat.</p>
    <pre class="message error" id="error" hidden></pre>
`;

/**
 * Story 429: llama.cpp's web UI in a frame, through the backend's `/llama/` pass-through. It never
 * starts the model: with Local AI off it points back at the switch, and with the backend
 * unreachable it says so rather than framing Chrome's error page.
 */
export class AiChat extends HTMLElement {
    constructor() {
        super();
        this.attachShadow({ mode: 'open' });
        this.shadowRoot!.adoptedStyleSheets = [styles];
        this.shadowRoot!.appendChild(template.content.cloneNode(true));
    }

    connectedCallback() {
        void this.load();
    }

    private $(id: string): HTMLElement {
        return this.shadowRoot!.getElementById(id)!;
    }

    private async load(): Promise<void> {
        try {
            const state = await AiService.getLocalAi();
            if (state.mode === 'off') {
                this.$('off').hidden = false;
            } else {
                const frame = document.createElement('iframe');
                frame.title = 'Local AI chat';
                frame.src = AiService.chatUrl();
                this.shadowRoot!.appendChild(frame);
            }
        } catch (err) {
            log.error('Failed to read Local AI for the chat page', err);
            const unreachable = err instanceof TypeError;
            const error = this.$('error');
            error.hidden = false;
            error.textContent = `${unreachable ? 'The backend is unreachable — offline, or the PC asleep.' : 'Failed to read Local AI.'}\n${err instanceof Error ? err.message : String(err)}`;
        } finally {
            this.$('loading').hidden = true;
        }
    }
}

if (!customElements.get('ai-chat')) {
    customElements.define('ai-chat', AiChat);
}
